-- Exact progression context/configuration payload tables and incident inventory 8.
-- Headers retain the existing immutable raw receipt. The repository inserts header
-- and payload in one transaction; raw retention cascades to these source-only rows.
-- No sealed migration, raw column or earlier report definition is changed.

CREATE TABLE IF NOT EXISTS telemetry_progression_context (
    boot_id BIGINT UNSIGNED NOT NULL,
    process_id BIGINT UNSIGNED NOT NULL,
    record_seq BIGINT UNSIGNED NOT NULL,
    schema_version SMALLINT UNSIGNED NOT NULL,
    record_kind TINYINT UNSIGNED NOT NULL,
    occurrence_utc_usec BIGINT NOT NULL,
    pctx_boot_id BIGINT UNSIGNED NOT NULL,
    pctx_process_id BIGINT UNSIGNED NOT NULL,
    pctx_sequence BIGINT UNSIGNED NOT NULL,
    pctx_session_boot_id BIGINT UNSIGNED NOT NULL,
    pctx_session_process_id BIGINT UNSIGNED NOT NULL,
    pctx_session_seq BIGINT UNSIGNED NOT NULL,
    pctx_subject_id BIGINT UNSIGNED NOT NULL,
    pctx_pid INT NOT NULL,
    pctx_environment_id BIGINT UNSIGNED NOT NULL,
    pctx_season_id BIGINT UNSIGNED NOT NULL,
    pctx_connection_boot_id BIGINT UNSIGNED NOT NULL,
    pctx_connection_process_id BIGINT UNSIGNED NOT NULL,
    pctx_connection_seq BIGINT UNSIGNED NOT NULL,
    pctx_source_boot_id BIGINT UNSIGNED NOT NULL,
    pctx_source_process_id BIGINT UNSIGNED NOT NULL,
    pctx_source_record_seq BIGINT UNSIGNED NOT NULL,
    pctx_ownership_boot_id BIGINT UNSIGNED NOT NULL,
    pctx_ownership_process_id BIGINT UNSIGNED NOT NULL,
    pctx_ownership_record_seq BIGINT UNSIGNED NOT NULL,
    pctx_account_token BIGINT UNSIGNED NOT NULL,
    pctx_start_usec BIGINT UNSIGNED NOT NULL,
    pctx_at_usec BIGINT UNSIGNED NOT NULL,
    pctx_start_utc_usec BIGINT NOT NULL,
    pctx_at_utc_usec BIGINT NOT NULL,
    pctx_config_id BIGINT UNSIGNED NOT NULL,
    pctx_configuration_record_seq BIGINT UNSIGNED NOT NULL,
    pctx_configuration_digest_0 BIGINT UNSIGNED NOT NULL,
    pctx_configuration_digest_1 BIGINT UNSIGNED NOT NULL,
    pctx_configuration_digest_2 BIGINT UNSIGNED NOT NULL,
    pctx_configuration_digest_3 BIGINT UNSIGNED NOT NULL,
    pctx_decision_level_cap INT NOT NULL,
    pctx_decision_good_assistance_gap INT NOT NULL,
    pctx_decision_evil_assistance_gap INT NOT NULL,
    pctx_decision_max_exp_level INT NOT NULL,
    pctx_next_threshold_xp BIGINT UNSIGNED NOT NULL,
    pctx_current_exp BIGINT NOT NULL,
    pctx_primary_class_mask INT UNSIGNED NOT NULL,
    pctx_secondary_class_mask INT UNSIGNED NOT NULL,
    pctx_build_version INT UNSIGNED NOT NULL,
    pctx_content_version INT UNSIGNED NOT NULL,
    pctx_classifier_version INT UNSIGNED NOT NULL,
    pctx_policy_version INT UNSIGNED NOT NULL,
    pctx_quality_flags INT UNSIGNED NOT NULL,
    pctx_flags INT UNSIGNED NOT NULL,
    pctx_base_stat_0 SMALLINT NOT NULL,
    pctx_base_stat_1 SMALLINT NOT NULL,
    pctx_base_stat_2 SMALLINT NOT NULL,
    pctx_base_stat_3 SMALLINT NOT NULL,
    pctx_base_stat_4 SMALLINT NOT NULL,
    pctx_base_stat_5 SMALLINT NOT NULL,
    pctx_base_stat_6 SMALLINT NOT NULL,
    pctx_base_stat_7 SMALLINT NOT NULL,
    pctx_base_stat_8 SMALLINT NOT NULL,
    pctx_base_stat_9 SMALLINT NOT NULL,
    pctx_effective_stat_0 SMALLINT NOT NULL,
    pctx_effective_stat_1 SMALLINT NOT NULL,
    pctx_effective_stat_2 SMALLINT NOT NULL,
    pctx_effective_stat_3 SMALLINT NOT NULL,
    pctx_effective_stat_4 SMALLINT NOT NULL,
    pctx_effective_stat_5 SMALLINT NOT NULL,
    pctx_effective_stat_6 SMALLINT NOT NULL,
    pctx_effective_stat_7 SMALLINT NOT NULL,
    pctx_effective_stat_8 SMALLINT NOT NULL,
    pctx_effective_stat_9 SMALLINT NOT NULL,
    pctx_formal_group_size INT UNSIGNED NOT NULL,
    pctx_current_level SMALLINT UNSIGNED NOT NULL,
    pctx_threshold_level SMALLINT UNSIGNED NOT NULL,
    pctx_threshold_catalog_version SMALLINT UNSIGNED NOT NULL,
    pctx_specialization SMALLINT UNSIGNED NOT NULL,
    pctx_race SMALLINT UNSIGNED NOT NULL,
    pctx_faction SMALLINT UNSIGNED NOT NULL,
    pctx_eligible_group_size SMALLINT UNSIGNED NOT NULL,
    pctx_highest_group_level SMALLINT UNSIGNED NOT NULL,
    pctx_assistance_level SMALLINT UNSIGNED NOT NULL,
    pctx_version SMALLINT UNSIGNED NOT NULL,
    pctx_rested_selection TINYINT UNSIGNED NOT NULL,
    pctx_rested_application TINYINT UNSIGNED NOT NULL,
    pctx_assistance TINYINT UNSIGNED NOT NULL,
    pctx_starting_level SMALLINT UNSIGNED NOT NULL,
    pctx_source_inventory_version SMALLINT UNSIGNED NOT NULL,
    pctx_boundary TINYINT UNSIGNED NOT NULL,
    pctx_source_kind TINYINT UNSIGNED NOT NULL,
    PRIMARY KEY (boot_id,process_id,record_seq),
    UNIQUE KEY uq_telemetry_pctx (pctx_boot_id,pctx_process_id,pctx_sequence),
    CONSTRAINT fk_telemetry_pctx_receipt FOREIGN KEY (boot_id,process_id,record_seq)
        REFERENCES telemetry_interval (boot_id,process_id,record_seq) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TRIGGER IF EXISTS telemetry_progression_pctx_insert;
DELIMITER $$
CREATE TRIGGER telemetry_progression_pctx_insert BEFORE INSERT ON telemetry_progression_context FOR EACH ROW BEGIN IF NEW.record_kind<>15 OR NEW.schema_version<>1 OR (NEW.pctx_boot_id IS NULL OR NEW.pctx_process_id IS NULL OR NEW.pctx_sequence IS NULL OR NEW.pctx_session_boot_id IS NULL OR NEW.pctx_session_process_id IS NULL OR NEW.pctx_session_seq IS NULL OR NEW.pctx_subject_id IS NULL OR NEW.pctx_pid IS NULL OR NEW.pctx_environment_id IS NULL OR NEW.pctx_season_id IS NULL OR NEW.pctx_connection_boot_id IS NULL OR NEW.pctx_connection_process_id IS NULL OR NEW.pctx_connection_seq IS NULL OR NEW.pctx_source_boot_id IS NULL OR NEW.pctx_source_process_id IS NULL OR NEW.pctx_source_record_seq IS NULL OR NEW.pctx_ownership_boot_id IS NULL OR NEW.pctx_ownership_process_id IS NULL OR NEW.pctx_ownership_record_seq IS NULL OR NEW.pctx_account_token IS NULL OR NEW.pctx_start_usec IS NULL OR NEW.pctx_at_usec IS NULL OR NEW.pctx_start_utc_usec IS NULL OR NEW.pctx_at_utc_usec IS NULL OR NEW.pctx_config_id IS NULL OR NEW.pctx_configuration_record_seq IS NULL OR NEW.pctx_configuration_digest_0 IS NULL OR NEW.pctx_configuration_digest_1 IS NULL OR NEW.pctx_configuration_digest_2 IS NULL OR NEW.pctx_configuration_digest_3 IS NULL OR NEW.pctx_decision_level_cap IS NULL OR NEW.pctx_decision_good_assistance_gap IS NULL OR NEW.pctx_decision_evil_assistance_gap IS NULL OR NEW.pctx_decision_max_exp_level IS NULL OR NEW.pctx_next_threshold_xp IS NULL OR NEW.pctx_current_exp IS NULL OR NEW.pctx_primary_class_mask IS NULL OR NEW.pctx_secondary_class_mask IS NULL OR NEW.pctx_build_version IS NULL OR NEW.pctx_content_version IS NULL OR NEW.pctx_classifier_version IS NULL OR NEW.pctx_policy_version IS NULL OR NEW.pctx_quality_flags IS NULL OR NEW.pctx_flags IS NULL OR NEW.pctx_base_stat_0 IS NULL OR NEW.pctx_base_stat_1 IS NULL OR NEW.pctx_base_stat_2 IS NULL OR NEW.pctx_base_stat_3 IS NULL OR NEW.pctx_base_stat_4 IS NULL OR NEW.pctx_base_stat_5 IS NULL OR NEW.pctx_base_stat_6 IS NULL OR NEW.pctx_base_stat_7 IS NULL OR NEW.pctx_base_stat_8 IS NULL OR NEW.pctx_base_stat_9 IS NULL OR NEW.pctx_effective_stat_0 IS NULL OR NEW.pctx_effective_stat_1 IS NULL OR NEW.pctx_effective_stat_2 IS NULL OR NEW.pctx_effective_stat_3 IS NULL OR NEW.pctx_effective_stat_4 IS NULL OR NEW.pctx_effective_stat_5 IS NULL OR NEW.pctx_effective_stat_6 IS NULL OR NEW.pctx_effective_stat_7 IS NULL OR NEW.pctx_effective_stat_8 IS NULL OR NEW.pctx_effective_stat_9 IS NULL OR NEW.pctx_formal_group_size IS NULL OR NEW.pctx_current_level IS NULL OR NEW.pctx_threshold_level IS NULL OR NEW.pctx_threshold_catalog_version IS NULL OR NEW.pctx_specialization IS NULL OR NEW.pctx_race IS NULL OR NEW.pctx_faction IS NULL OR NEW.pctx_eligible_group_size IS NULL OR NEW.pctx_highest_group_level IS NULL OR NEW.pctx_assistance_level IS NULL OR NEW.pctx_version IS NULL OR NEW.pctx_rested_selection IS NULL OR NEW.pctx_rested_application IS NULL OR NEW.pctx_assistance IS NULL OR NEW.pctx_starting_level IS NULL OR NEW.pctx_source_inventory_version IS NULL OR NEW.pctx_boundary IS NULL OR NEW.pctx_source_kind IS NULL OR NEW.pctx_boot_id <> NEW.boot_id OR NEW.pctx_process_id <> NEW.process_id OR NEW.pctx_sequence = 0 OR NEW.pctx_at_utc_usec <> NEW.occurrence_utc_usec OR NEW.pctx_version <> 1 OR NEW.pctx_source_inventory_version <> 1 OR NEW.pctx_current_level = 0 OR NEW.pctx_boundary NOT BETWEEN 1 AND 6 OR NEW.pctx_source_kind NOT IN (0,1,2,6) OR NEW.pctx_start_usec > NEW.pctx_at_usec OR (NEW.pctx_flags & ~2097151) <> 0 OR (NEW.pctx_quality_flags & ~1023) <> 0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='invalid pctx observation'; END IF; IF NOT EXISTS (SELECT 1 FROM telemetry_interval r WHERE r.boot_id=NEW.boot_id AND r.process_id=NEW.process_id AND r.record_seq=NEW.record_seq AND r.schema_version=NEW.schema_version AND r.record_kind=NEW.record_kind AND r.occurrence_utc_usec=NEW.occurrence_utc_usec) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='progression raw receipt mismatch'; END IF; END$$
DELIMITER ;

DROP TRIGGER IF EXISTS telemetry_progression_pctx_update;
DELIMITER $$
CREATE TRIGGER telemetry_progression_pctx_update BEFORE UPDATE ON telemetry_progression_context FOR EACH ROW BEGIN IF NOT (NEW.boot_id <=> OLD.boot_id AND NEW.process_id <=> OLD.process_id AND NEW.record_seq <=> OLD.record_seq AND NEW.schema_version <=> OLD.schema_version AND NEW.record_kind <=> OLD.record_kind AND NEW.occurrence_utc_usec <=> OLD.occurrence_utc_usec AND NEW.pctx_boot_id <=> OLD.pctx_boot_id AND NEW.pctx_process_id <=> OLD.pctx_process_id AND NEW.pctx_sequence <=> OLD.pctx_sequence AND NEW.pctx_session_boot_id <=> OLD.pctx_session_boot_id AND NEW.pctx_session_process_id <=> OLD.pctx_session_process_id AND NEW.pctx_session_seq <=> OLD.pctx_session_seq AND NEW.pctx_subject_id <=> OLD.pctx_subject_id AND NEW.pctx_pid <=> OLD.pctx_pid AND NEW.pctx_environment_id <=> OLD.pctx_environment_id AND NEW.pctx_season_id <=> OLD.pctx_season_id AND NEW.pctx_connection_boot_id <=> OLD.pctx_connection_boot_id AND NEW.pctx_connection_process_id <=> OLD.pctx_connection_process_id AND NEW.pctx_connection_seq <=> OLD.pctx_connection_seq AND NEW.pctx_source_boot_id <=> OLD.pctx_source_boot_id AND NEW.pctx_source_process_id <=> OLD.pctx_source_process_id AND NEW.pctx_source_record_seq <=> OLD.pctx_source_record_seq AND NEW.pctx_ownership_boot_id <=> OLD.pctx_ownership_boot_id AND NEW.pctx_ownership_process_id <=> OLD.pctx_ownership_process_id AND NEW.pctx_ownership_record_seq <=> OLD.pctx_ownership_record_seq AND NEW.pctx_account_token <=> OLD.pctx_account_token AND NEW.pctx_start_usec <=> OLD.pctx_start_usec AND NEW.pctx_at_usec <=> OLD.pctx_at_usec AND NEW.pctx_start_utc_usec <=> OLD.pctx_start_utc_usec AND NEW.pctx_at_utc_usec <=> OLD.pctx_at_utc_usec AND NEW.pctx_config_id <=> OLD.pctx_config_id AND NEW.pctx_configuration_record_seq <=> OLD.pctx_configuration_record_seq AND NEW.pctx_configuration_digest_0 <=> OLD.pctx_configuration_digest_0 AND NEW.pctx_configuration_digest_1 <=> OLD.pctx_configuration_digest_1 AND NEW.pctx_configuration_digest_2 <=> OLD.pctx_configuration_digest_2 AND NEW.pctx_configuration_digest_3 <=> OLD.pctx_configuration_digest_3 AND NEW.pctx_decision_level_cap <=> OLD.pctx_decision_level_cap AND NEW.pctx_decision_good_assistance_gap <=> OLD.pctx_decision_good_assistance_gap AND NEW.pctx_decision_evil_assistance_gap <=> OLD.pctx_decision_evil_assistance_gap AND NEW.pctx_decision_max_exp_level <=> OLD.pctx_decision_max_exp_level AND NEW.pctx_next_threshold_xp <=> OLD.pctx_next_threshold_xp AND NEW.pctx_current_exp <=> OLD.pctx_current_exp AND NEW.pctx_primary_class_mask <=> OLD.pctx_primary_class_mask AND NEW.pctx_secondary_class_mask <=> OLD.pctx_secondary_class_mask AND NEW.pctx_build_version <=> OLD.pctx_build_version AND NEW.pctx_content_version <=> OLD.pctx_content_version AND NEW.pctx_classifier_version <=> OLD.pctx_classifier_version AND NEW.pctx_policy_version <=> OLD.pctx_policy_version AND NEW.pctx_quality_flags <=> OLD.pctx_quality_flags AND NEW.pctx_flags <=> OLD.pctx_flags AND NEW.pctx_base_stat_0 <=> OLD.pctx_base_stat_0 AND NEW.pctx_base_stat_1 <=> OLD.pctx_base_stat_1 AND NEW.pctx_base_stat_2 <=> OLD.pctx_base_stat_2 AND NEW.pctx_base_stat_3 <=> OLD.pctx_base_stat_3 AND NEW.pctx_base_stat_4 <=> OLD.pctx_base_stat_4 AND NEW.pctx_base_stat_5 <=> OLD.pctx_base_stat_5 AND NEW.pctx_base_stat_6 <=> OLD.pctx_base_stat_6 AND NEW.pctx_base_stat_7 <=> OLD.pctx_base_stat_7 AND NEW.pctx_base_stat_8 <=> OLD.pctx_base_stat_8 AND NEW.pctx_base_stat_9 <=> OLD.pctx_base_stat_9 AND NEW.pctx_effective_stat_0 <=> OLD.pctx_effective_stat_0 AND NEW.pctx_effective_stat_1 <=> OLD.pctx_effective_stat_1 AND NEW.pctx_effective_stat_2 <=> OLD.pctx_effective_stat_2 AND NEW.pctx_effective_stat_3 <=> OLD.pctx_effective_stat_3 AND NEW.pctx_effective_stat_4 <=> OLD.pctx_effective_stat_4 AND NEW.pctx_effective_stat_5 <=> OLD.pctx_effective_stat_5 AND NEW.pctx_effective_stat_6 <=> OLD.pctx_effective_stat_6 AND NEW.pctx_effective_stat_7 <=> OLD.pctx_effective_stat_7 AND NEW.pctx_effective_stat_8 <=> OLD.pctx_effective_stat_8 AND NEW.pctx_effective_stat_9 <=> OLD.pctx_effective_stat_9 AND NEW.pctx_formal_group_size <=> OLD.pctx_formal_group_size AND NEW.pctx_current_level <=> OLD.pctx_current_level AND NEW.pctx_threshold_level <=> OLD.pctx_threshold_level AND NEW.pctx_threshold_catalog_version <=> OLD.pctx_threshold_catalog_version AND NEW.pctx_specialization <=> OLD.pctx_specialization AND NEW.pctx_race <=> OLD.pctx_race AND NEW.pctx_faction <=> OLD.pctx_faction AND NEW.pctx_eligible_group_size <=> OLD.pctx_eligible_group_size AND NEW.pctx_highest_group_level <=> OLD.pctx_highest_group_level AND NEW.pctx_assistance_level <=> OLD.pctx_assistance_level AND NEW.pctx_version <=> OLD.pctx_version AND NEW.pctx_rested_selection <=> OLD.pctx_rested_selection AND NEW.pctx_rested_application <=> OLD.pctx_rested_application AND NEW.pctx_assistance <=> OLD.pctx_assistance AND NEW.pctx_starting_level <=> OLD.pctx_starting_level AND NEW.pctx_source_inventory_version <=> OLD.pctx_source_inventory_version AND NEW.pctx_boundary <=> OLD.pctx_boundary AND NEW.pctx_source_kind <=> OLD.pctx_source_kind) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='immutable progression source'; END IF; END$$
DELIMITER ;

